package com.bank.transfer.service;

import com.bank.transfer.dto.TransferReceipt;
import com.bank.transfer.exception.InsufficientFundsException;
import com.bank.transfer.model.Account;
import com.bank.transfer.repository.AccountRepository;
import reactor.core.publisher.Mono;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final AccountRepository repo;
    public TransferService(AccountRepository repo) { this.repo = repo; }

    // Returns a LAZY Mono. The debit/credit side effects run ONLY when subscribed.
    public Mono<TransferReceipt> transfer(String fromId, String toId, BigDecimal amount) {
        return repo.findById(fromId)
            .zipWith(repo.findById(toId))
            .flatMap(pair -> {
                Account from = pair.getT1();
                Account to = pair.getT2();
                if (from.getBalance().compareTo(amount) < 0) {
                    // This error is only emitted when something subscribes.
                    return Mono.error(new InsufficientFundsException(
                            "Insufficient funds in " + fromId));
                }
                from.debit(amount);   // SIDE EFFECT — happens only on subscribe
                to.credit(amount);    // SIDE EFFECT — happens only on subscribe
                log.info(() -> "Transferred " + amount + " from " + fromId + " to " + toId);
                return Mono.just(new TransferReceipt("TXF-00001", fromId, toId, amount, "COMPLETED"));
            });
    }
}
