package com.bank.transfer.service;

import com.bank.transfer.dto.TransferReceipt;
import com.bank.transfer.exception.InsufficientFundsException;
import com.bank.transfer.model.Account;
import com.bank.transfer.repository.AccountRepository;
import org.junit.jupiter.api.*;
import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;
import java.math.BigDecimal;

class TransferServiceTest {
    private AccountRepository repo;
    private TransferService service;

    @BeforeEach void setUp() {
        repo = new AccountRepository();
        repo.save(new Account("SAV2001", "Rajesh", new BigDecimal("1000000")));
        repo.save(new Account("CUR3001", "Priya", new BigDecimal("250000")));
        service = new TransferService(repo);
    }

    // WRONG WAY — demonstrates the vacuous pass. The Mono is never subscribed,
    // so the debit/credit NEVER run. This assertion passes but tested NOTHING.
    @Test void wrongWay_neverSubscribed_vacuousPass() {
        BigDecimal rentAmount = new BigDecimal("50000");
        service.transfer("SAV2001", "CUR3001", rentAmount); // built, NOT subscribed → no-op
        // Balance is unchanged because the chain never ran — a false sense of safety.
        Assertions.assertEquals(new BigDecimal("1000000"),
                repo.findById("SAV2001").block().getBalance(),
                "Debit never happened because we never subscribed");
    }

    // RIGHT WAY — StepVerifier subscribes, asserts the emission, and verifyComplete()
    // is the terminal call that actually runs the chain.
    @Test void rightWay_subscribedWithStepVerifier() {
        BigDecimal rentAmount = new BigDecimal("50000");
        StepVerifier.create(service.transfer("SAV2001", "CUR3001", rentAmount))
                .expectNextMatches(r -> r.getStatus().equals("COMPLETED")
                        && r.getAmount().compareTo(rentAmount) == 0)
                .verifyComplete();   // ← terminal: subscribes, runs, blocks until done

        // Now the side effects really happened.
        Assertions.assertEquals(new BigDecimal("950000"), repo.findById("SAV2001").block().getBalance());
        Assertions.assertEquals(new BigDecimal("300000"), repo.findById("CUR3001").block().getBalance());
    }

    // RIGHT WAY for errors — expectError on a SUBSCRIBED chain surfaces the failure.
    @Test void rightWay_insufficientFundsEmitsError() {
        BigDecimal huge = new BigDecimal("5000000");
        StepVerifier.create(service.transfer("SAV2001", "CUR3001", huge))
                .expectError(InsufficientFundsException.class)
                .verify();           // ← terminal: without this, nothing runs
    }

    // TRAP — building a StepVerifier but FORGETTING the terminal verify also tests nothing.
    @Test void trap_missingTerminalVerify_doesNotRun() {
        // StepVerifier.create(service.transfer(...)).expectComplete();  // <-- no verify() = no subscribe
        // We instead show the correct terminal call is required:
        StepVerifier.create(Mono.just("ok")).expectNext("ok").verifyComplete();
        Assertions.assertTrue(true, "Terminal verify() is what makes the test real");
    }
}
